SourceCode.Declaration:
class TFMLogicContextInfoContext extends TFMLogicContextFunctions
{
    ItemId itemId;
    InventTable inventTable;
}

Method.Source:
public static TFMLogicContextInfoContext Construct()
{
    TFMLogicContextInfoContext infoSetup = new TFMLogicContextInfoContext();
    return infoSetup;
}

/// <summary>
///
/// </summary>
protected void new()
{
    super();
    outputType = TFMLogicContextTypes::String;
}

public ItemId parmItemId(ItemId _itemId = itemId)
{
    ItemId = _itemId;
    inventTable = InventTable::find(_ItemId);        
    return ItemId;
}

[DataContract(classStr(TFMInfoContextContract))]
public Object process()
{
    TFMInfoContextContract      contract = new TFMInfoContextContract();
    str                         html;
    InventQuarantineOrder       qOrder;

    if (context.getFieldContent(extendedTypeStr(InventQuarantineId)))
    {
        //Init ItemId
        qOrder = InventQuarantineOrder::find(context.getFieldContent(extendedTypeStr(InventQuarantineId)));
        context.addFieldContent(extendedTypeStr(ItemId),qOrder.ItemId);

        html = TFMHelper::makeDocurefHTML(qOrder);

        contract.parmQOrderInformation(html);
    }

    if ((context.getFieldContent(extendedTypeStr(ItemId)) || context.getFieldContent(TFMConstants::ItemNumber())))
    {
        //Init ItemId
        this.parmItemId(context.getFieldContent(extendedTypeStr(ItemId)) ? context.getFieldContent(extendedTypeStr(ItemId)) : context.getFieldContent(TFMConstants::ItemNumber()));

        html = TFMHelper::makeItemHTML(inventTable);

        contract.parmItemInfo(html);
    }




    return contract;
}
